int
sc_pkcs15_bind_internal(struct sc_pkcs15_card *p15card, struct sc_aid *aid)
{
	struct sc_path tmppath;
	struct sc_card    *card = p15card->card;
	struct sc_context *ctx  = card->ctx;
	struct sc_pkcs15_tokeninfo tokeninfo;
	struct sc_pkcs15_df *df;
	const struct sc_app_info *info = NULL;
	unsigned char *buf = NULL;
	size_t len;
	int    err, ok = 0;

	LOG_FUNC_CALLED(ctx);
	/* Enumerate apps now */
	if (card->app_count < 0) {
		err = sc_enum_apps(card);
		if (err != SC_SUCCESS)
			sc_log(ctx, "unable to enumerate apps: %s", sc_strerror(err));
	}
	p15card->file_app = sc_file_new();
	if (p15card->file_app == NULL) {
		err = SC_ERROR_OUT_OF_MEMORY;
		goto end;
	}

	sc_format_path("3F005015", &p15card->file_app->path);

	info = sc_find_app(card, aid);
	if (info)   {
		sc_log(ctx, "bind to application('%s',aid:'%s')", info->label, sc_dump_hex(info->aid.value, info->aid.len));
		p15card->app = sc_dup_app_info(info);
		if (!p15card->app)   {
			err = SC_ERROR_OUT_OF_MEMORY;
			goto end;
		}

		if (info->path.len)
			p15card->file_app->path = info->path;

		if (info->ddo.value && info->ddo.len)
			parse_ddo(p15card, info->ddo.value, info->ddo.len);

	}
	else if (aid)   {
		sc_log(ctx, "Application '%s' not found", sc_dump_hex(aid->value, aid->len));
		err = SC_ERROR_INVALID_ARGUMENTS;
		goto end;
	}
	sc_log(ctx, "application path '%s'", sc_print_path(&p15card->file_app->path));

	/* Check if pkcs15 directory exists */
	err = sc_select_file(card, &p15card->file_app->path, NULL);

	/* If the above test failed on cards without EF(DIR),
	 * try to continue read ODF from 3F005031. -aet
	 */
	if ((err != SC_SUCCESS) && (card->app_count < 1)) {
		sc_format_path("3F00", &p15card->file_app->path);
		err = SC_SUCCESS;
	}

	if (err < 0)   {
		sc_log (ctx, "Cannot select application path");
		goto end;
	}

	if (p15card->file_odf == NULL) {
		/* check if an ODF is present; we don't know yet whether we have a pkcs15 card */
		sc_format_path("5031", &tmppath);
		err = sc_pkcs15_make_absolute_path(&p15card->file_app->path, &tmppath);
		if (err != SC_SUCCESS)   {
			sc_log(ctx, "Cannot make absolute path to EF(ODF); error:%i", err);
			goto end;
		}
		sc_log(ctx, "absolute path to EF(ODF) %s", sc_print_path(&tmppath));
		err = sc_select_file(card, &tmppath, &p15card->file_odf);
	}
	else {
		tmppath = p15card->file_odf->path;
		sc_file_free(p15card->file_odf);
		p15card->file_odf = NULL;
		err = sc_select_file(card, &tmppath, &p15card->file_odf);
	}

	if (err != SC_SUCCESS) {
		sc_log(ctx, "EF(ODF) not found in '%s'", sc_print_path(&tmppath));
		goto end;
	}

	len = p15card->file_odf->size;
	if (!len) {
		sc_log(ctx, "EF(ODF) is empty");
		goto end;
	}
	if (len > MAX_FILE_SIZE) {
		sc_log(ctx, "EF(ODF) too large");
		goto end;
	}
	buf = malloc(len);
	if(buf == NULL)
		LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);

	err = -1; /* file state: not in cache */
	if (p15card->opts.use_file_cache) {
		err = sc_pkcs15_read_cached_file(p15card, &tmppath, &buf, &len);
		if (err == SC_SUCCESS)
			err = len;
	}
	if (err < 0) {
		err = sc_read_binary(card, 0, buf, len, 0);
		if (err < 2) {
			if (err < 0) {
				sc_log(ctx, "read EF(ODF) file error: %s", sc_strerror(err));
			} else {
				err = SC_ERROR_PKCS15_APP_NOT_FOUND;
				sc_log(ctx, "Invalid content of EF(ODF): %s", sc_strerror(err));
			}
			goto end;
		}
		/* sc_read_binary may return less than requested */
		len = err;

		if (p15card->opts.use_file_cache) {
			sc_pkcs15_cache_file(p15card, &tmppath, buf, len);
		}
	}

	if (parse_odf(buf, len, p15card)) {
		err = SC_ERROR_PKCS15_APP_NOT_FOUND;
		sc_log(ctx, "Unable to parse ODF");
		goto end;
	}
	free(buf);
	buf = NULL;

	sc_log(ctx, "The following DFs were found:");
	for (df = p15card->df_list; df; df = df->next)
		sc_log(ctx, "  DF type %u, path %s, index %u, count %d", df->type,
				sc_print_path(&df->path), df->path.index, df->path.count);

	if (p15card->file_tokeninfo == NULL) {
		sc_format_path("5032", &tmppath);
		err = sc_pkcs15_make_absolute_path(&p15card->file_app->path, &tmppath);
		if (err != SC_SUCCESS)   {
			sc_log(ctx, "Cannot make absolute path to EF(TokenInfo); error:%i", err);
			goto end;
		}
		sc_log(ctx, "absolute path to EF(TokenInfo) %s", sc_print_path(&tmppath));
	}
	else {
		tmppath = p15card->file_tokeninfo->path;
		sc_file_free(p15card->file_tokeninfo);
		p15card->file_tokeninfo = NULL;
	}

	err = sc_select_file(card, &tmppath, &p15card->file_tokeninfo);
	if (err)   {
		sc_log(ctx, "cannot select EF(TokenInfo) file: %s", sc_strerror(err));
		goto end;
	}

	len = p15card->file_tokeninfo->size;
	if (!len) {
		sc_log(ctx, "EF(TokenInfo) is empty");
		goto end;
	}
	if (len > MAX_FILE_SIZE) {
		sc_log(ctx, "EF(TokenInfo) too large");
		goto end;
	}
	buf = malloc(len);
	if(buf == NULL)
		LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);

	err = -1; /* file state: not in cache */
	if (p15card->opts.use_file_cache) {
		err = sc_pkcs15_read_cached_file(p15card, &tmppath, &buf, &len);
		if (err == SC_SUCCESS)
			err = len;
	}
	if (err < 0) {
		err = sc_read_binary(card, 0, buf, len, 0);
		if (err <= 2) {
			if (err < 0)   {
				sc_log(ctx, "read EF(TokenInfo) file error: %s", sc_strerror(err));
			} else {
				err = SC_ERROR_PKCS15_APP_NOT_FOUND;
				sc_log(ctx, "Invalid content of EF(TokenInfo): %s", sc_strerror(err));
			}
			goto end;
		}

static int dnie_select_file(struct sc_card *card,
			    const struct sc_path *in_path,
			    struct sc_file **file_out)
{
	int res = SC_SUCCESS;
	sc_context_t *ctx = NULL;
	unsigned char tmp_path[sizeof(DNIE_MF_NAME)];
	int reminder = 0;

	if (!card || !card->ctx || !in_path)
		return SC_ERROR_INVALID_ARGUMENTS;
	ctx = card->ctx;

	LOG_FUNC_CALLED(ctx);

	switch (in_path->type) {
	case SC_PATH_TYPE_FILE_ID:
		/* pathlen must be of len=2 */
		/* 
		 * gscriptor shows that DNIe also handles 
		 * Select child DF (p1=1) and Select EF (p1=2),
		 * but we'll use P1=0 as general solution for all cases
		 *
		 * According iso7816-4 sect 7.1.1  pathlen==0 implies
		 * select MF, but this case is not supported by DNIe
		 */
		if (in_path->len != 2)
			LOG_FUNC_RETURN(ctx, SC_ERROR_INVALID_ARGUMENTS);
		sc_log_hex(ctx, "select_file(ID)", in_path->value, in_path->len);
		res = dnie_compose_and_send_apdu(card, in_path->value, in_path->len, 0, file_out);
		break;
	case SC_PATH_TYPE_DF_NAME:
		sc_log_hex(ctx, "select_file(NAME)", in_path->value, in_path->len);
		res = dnie_compose_and_send_apdu(card, in_path->value, in_path->len, 4, file_out);
		break;
	case SC_PATH_TYPE_PATH:
		if ((in_path->len == 0) || ((in_path->len & 1) != 0)) /* not divisible by 2 */
			LOG_FUNC_RETURN(ctx, SC_ERROR_INVALID_ARGUMENTS);

		sc_log_hex(ctx, "select_file(PATH): requested", in_path->value, in_path->len);

		/* convert to SC_PATH_TYPE_FILE_ID */
		res = sc_lock(card); /* lock to ensure path traversal */
		LOG_TEST_RET(ctx, res, "sc_lock() failed");
		if (memcmp(in_path->value, "\x3F\x00", 2) == 0) {
			/* if MF, use the name as path */
			strcpy((char *)tmp_path, DNIE_MF_NAME);
			sc_log_hex(ctx, "select_file(NAME): requested", tmp_path, sizeof(DNIE_MF_NAME) - 1);
			res = dnie_compose_and_send_apdu(card, tmp_path, sizeof(DNIE_MF_NAME) - 1, 4, file_out);
			if (res != SC_SUCCESS) {
				sc_unlock(card);
				LOG_TEST_RET(ctx, res, "select_file(NAME) failed");
			}
			tmp_path[2] = 0;
			reminder = in_path->len - 2;
		} else {
			tmp_path[2] = 0;
			reminder = in_path->len;
		}
		while (reminder > 0) {
			tmp_path[0] = in_path->value[in_path->len - reminder];
			tmp_path[1] = in_path->value[1 + in_path->len - reminder];
			sc_log(ctx, "select_file(PATH): requested:%s ", sc_dump_hex(tmp_path, 2));
			res = dnie_compose_and_send_apdu(card, tmp_path, 2, 0, file_out);
			if (res != SC_SUCCESS) {
				sc_unlock(card);
				LOG_TEST_RET(ctx, res, "select_file(PATH) failed");
			}
			reminder -= 2;
		}
		sc_unlock(card);
		break;
	case SC_PATH_TYPE_FROM_CURRENT:
		LOG_FUNC_RETURN(ctx, SC_ERROR_NO_CARD_SUPPORT);
		break;
	case SC_PATH_TYPE_PARENT:
		/* Hey!! Manual doesn't says anything on this, but
		 * gscriptor shows that this type is supported
		 */
		sc_log(ctx, "select_file(PARENT)");
		/* according iso7816-4 sect 7.1.1 shouldn't have any parameters */
		if (in_path->len != 0)
			LOG_FUNC_RETURN(ctx, SC_ERROR_INVALID_ARGUMENTS);
		res = dnie_compose_and_send_apdu(card, NULL, 0, 3, file_out);
		break;
	default:
		LOG_FUNC_RETURN(ctx, SC_ERROR_INVALID_ARGUMENTS);
		break;
	}

	/* as last step clear data cache and return */
	dnie_clear_cache(GET_DNIE_PRIV_DATA(card));
	LOG_FUNC_RETURN(ctx, res);
}

static int dnie_compose_and_send_apdu(sc_card_t *card, const u8 *path, size_t pathlen,
					u8 p1, sc_file_t **file_out)
{
	int res = 0;
	sc_apdu_t apdu;
	u8 rbuf[MAX_RESP_BUFFER_SIZE];
	sc_file_t *file = NULL;

	sc_context_t *ctx = NULL;

	if (!card || !card->ctx)
		return SC_ERROR_INVALID_ARGUMENTS;
	ctx = card->ctx;

	LOG_FUNC_CALLED(ctx);

	dnie_format_apdu(card, &apdu, SC_APDU_CASE_4_SHORT, 0xA4, p1, 0, 
					sc_get_max_recv_size(card), pathlen,
					rbuf, sizeof(rbuf), path, pathlen);
	if (p1 == 3)
		apdu.cse= SC_APDU_CASE_1;

	if (file_out == NULL)
		apdu.cse = SC_APDU_CASE_4_SHORT;

	res = sc_transmit_apdu(card, &apdu);
	if ((res != SC_SUCCESS) || (file_out == NULL))
		LOG_TEST_RET(ctx, res, "SelectFile() APDU transmit failed");
	if (file_out == NULL) {
		if (apdu.sw1 == 0x61)
			SC_FUNC_RETURN(ctx, SC_LOG_DEBUG_VERBOSE, 0);
		SC_FUNC_RETURN(ctx, SC_LOG_DEBUG_VERBOSE,
			       sc_check_sw(card, apdu.sw1, apdu.sw2));
	}

	/* analyze response. if FCI, try to parse */
	res = sc_check_sw(card, apdu.sw1, apdu.sw2);
	if (res != SC_SUCCESS) {
		LOG_TEST_RET(ctx, res, "SelectFile() check_sw failed");
	}
	if ((apdu.resplen < 2) || (apdu.resp[0] == 0x00)) {
		LOG_FUNC_RETURN(ctx, SC_ERROR_UNKNOWN_DATA_RECEIVED);
	}

	/* finally process FCI response */
	file = sc_file_new();
	if (file == NULL) {
		LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);
	}
	res = card->ops->process_fci(card, file, apdu.resp + 2, apdu.resp[1]);
	sc_file_free(*file_out);
	*file_out = file;
	LOG_FUNC_RETURN(ctx, res);
}

